import { newsService } from './news-service.js';
import { profilePage, pagination } from './management.js';
import { authService } from './auth-service.js';
import { escapeHtml, backgroundMedia } from './components.js';
import { config } from './config.js';
import { dataService, features, rules, playProgress } from './data.js';
import { button, pageHeader, sectionHeader, newsCard, featureCard, notice, table, dateLabel, badge, sectionCue } from './components.js';
export async function home() {
  const [articles, settings] = await Promise.all([dataService.getNews(), dataService.getRealm()]);
  const realm = Object.fromEntries(Object.entries(settings).map(([key, value]) => [key, escapeHtml(value)]));
  return `<div class="home-page"><section class="hero">${backgroundMedia()}<div class="container hero-content"><div class="hero-kicker"><span></span> WORLD OF WARCRAFT · PRIVATE REALM</div><h1>The frozen<br>throne <em>awaits.</em></h1><p>Return to Northrend. Gather your allies.<br>Forge a new legend in Wrath of the Lich King.</p><div class="hero-actions">${button('Play free <span aria-hidden="true">⚔</span>', '#/play')}${button('Explore the realm <span aria-hidden="true">→</span>', '#/server', 'outline button--glint')}</div><div class="hero-details"><span>${realm.expansion}</span><i></i><span>${realm.clientVersion}</span><i></i><span>LEVEL ${realm.maxLevel}</span></div></div><div class="hero-bottom container"><span>A NEW REALM. AN UNFINISHED LEGEND.</span></div><section class="realm-strip"><div class="container realm-strip-inner"><div class="realm-identity"><span class="status-dot"></span><div><strong>${realm.name}</strong><span>${realm.status}</span></div>${badge('PRE-LAUNCH')}</div><div class="realm-stat"><span>EXPANSION</span><strong>${realm.expansion}</strong></div><div class="realm-stat"><span>EXPERIENCE</span><strong>${realm.experience}</strong></div><div class="realm-stat"><span>MAX LEVEL</span><strong>${realm.maxLevel}</strong></div><a class="text-link" href="#/server">Realm information <span>→</span></a></div></section></section><section class="home-section container" id="realm-intro">${sectionHeader('YOUR NEXT CHAPTER', 'Rediscover the world of Azeroth')}<div class="server-grid"><div class="server-intro"><p class="lead">From your first quest to the frozen gates of Icecrown.</p><p>Explore Northrend, assemble your dungeon party, and find a guild to call home. A familiar world gives every adventurer a different story.</p>${button('Explore realm information →', '#/server', 'outline')}</div><div class="panel"><p class="eyebrow">THE PROPOSED REALM</p><h3>${realm.name}</h3><dl class="details-list"><div><dt>Expansion</dt><dd>${realm.expansion}</dd></div><div><dt>Client version</dt><dd>${realm.clientVersion}</dd></div><div><dt>Experience</dt><dd>${realm.experience}</dd></div><div><dt>Maximum level</dt><dd>${realm.maxLevel}</dd></div><div><dt>Status</dt><dd>${realm.status}</dd></div></dl>${authService.state.account?.role === 'admin' ? button('Edit realm information →', '#/admin/realm', 'outline') : ''}</div></div><a class="text-link section-next" href="#latest" data-scroll="latest">Read the realm journal <span aria-hidden="true">↓</span></a></section><section class="home-section container" id="latest">${sectionHeader('NEWS & ANNOUNCEMENTS', 'Chronicles of the realm', '<a class="text-link" href="#/news">View all news <span>→</span></a>')}<div class="news-grid">${articles.map(newsCard).join('')}</div><p class="content-note">Realm journal · Latest published updates</p></section><section class="features-section"><div class="container home-section">${sectionCue('top')}${sectionHeader('THE CALL OF NORTHREND', 'A world worth fighting for')}<div class="feature-grid">${features.map(featureCard).join('')}</div><div class="journey-panel"><div><p class="eyebrow">FOR THE HORDE. FOR THE ALLIANCE.</p><h2>Choose your faction.<br>Forge your legacy.</h2><p>Your journey from the first quest to the gates of Icecrown.<br>Prepare to enter the world of ${config.name}.</p></div><div class="journey-action"><span class="journey-mark" aria-hidden="true">⚔</span>${button('Join the adventure →', '#/play')}<span>${realm.expansion} · ${realm.clientVersion}</span></div></div></div></section>${sectionCue()}</div>`;
}
export async function newsPage(params = new URLSearchParams()) {
  const [result, categories] = await Promise.all([newsService.list(params), newsService.categories()]);
  const active = params.get('category') || '';
  return `${pageHeader('THE REALM JOURNAL', 'Stories from a world in the making.', 'Announcements, development notes, and the people behind the adventure.')}<section class="container page-section"><div class="tabs" aria-label="News categories">${[{ id: '', name: 'All' }, ...categories].map(category => `<a class="tab ${active === category.id ? 'is-active' : ''}" href="#/news?category=${encodeURIComponent(category.id)}" ${active === category.id ? 'aria-current="page"' : ''}>${escapeHtml(category.name)}</a>`).join('')}</div>${authService.state.account?.role === 'admin' ? '<div class="management-actions">' + button('Manage news →', '#/admin') + button('New article', '#/admin/new', 'outline') + '</div>' : ''}<div class="news-grid" data-motion="vertical">${result.items.map(newsCard).join('')}</div>${result.items.length ? '' : notice('No published articles in this category.')}${pagination(result, params, '#/news')}</section>`;
}
export async function articlePage(id) {
  const article = await newsService.article(id);
  return `<article class="container article page-section"><a class="text-link" href="#/news">← Back to the journal</a><div class="news-meta">${badge(escapeHtml(article.categoryName))}<time datetime="${article.publishedAt}">${dateLabel(article.publishedAt)}</time></div><h1>${escapeHtml(article.title)}</h1><p class="content-note">By ${escapeHtml(article.author.name)} · Updated ${dateLabel(article.updatedAt)}</p>${article.imageUrl ? `<img class="article-image" src="${escapeHtml(article.imageUrl)}" alt="${escapeHtml(article.imageAlt)}">` : ''}<div class="article-body">${escapeHtml(article.content)}</div>${article.isDemo ? notice('Demonstration article · Example project content.') : ''}${authService.state.account?.role === 'admin' ? button('Edit article →', '#/admin/edit/' + encodeURIComponent(article.id), 'outline') : ''}</article>`;
}
export async function serverPage() {
  const settings = await dataService.getRealm();
  const realm = Object.fromEntries(Object.entries(settings).map(([key, value]) => [key, escapeHtml(value)]));
  return `${pageHeader('MEET YOUR NEXT HOME', 'A familiar world. A fresh perspective.', 'An independent realm concept inspired by the journey, the challenge, and the community.')}<section class="container page-section"><div class="server-grid"><div class="panel"><div class="panel-heading"><h2>${realm.name}</h2>${badge(realm.status)}</div>${authService.state.account?.role === 'admin' ? button('Edit realm information →', '#/admin/realm', 'outline') : ''}<dl class="details-list">${[['Expansion', realm.expansion], ['Client version', realm.clientVersion], ['Maximum level', realm.maxLevel], ['Experience rate', realm.experience], ['Online players', 'Not connected'], ['Launch date', 'To be announced'], ['Realm address', config.connection]].map(([k,v]) => `<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl></div><div class="server-intro"><p class="eyebrow">THE PHILOSOPHY</p><h2>Worth exploring.<br>Worth coming home to.</h2><p>We believe the best memories happen when the world gives you a reason to slow down, team up, and take the long way home.</p><p>A carefully considered Wrath-era foundation is our starting point. Detailed features and progression plans will be shared as development continues.</p>${button('Explore the getting-started guide →', '#/play', 'outline')}</div></div>${notice('This is a website foundation. Realm settings are illustrative and no live game server is connected.')}<div class="feature-grid">${features.map(featureCard).join('')}</div></section>`;
}
export async function playPage() {
  const settings = await dataService.getRealm();
  const realm = Object.fromEntries(Object.entries(settings).map(([key, value]) => [key, escapeHtml(value)]));
  const account = authService.state.account;
  const completedSteps = [Boolean(account), Boolean(account) && playProgress.hasDownloadPreview(account?.id)];
  const steps = [['Create your account', account ? 'Your website account is ready. You are signed in and ready for the next step.' : 'Your adventure begins with an account. Sign in or create a local website test account to complete this step.', button(account ? 'My profile →' : 'Login or create an account →', account ? '#/account' : '#/account?returnTo=%23%2Fplay', 'outline')], ['Prepare your client', `You’ll need a compatible ${realm.clientVersion} client. An official download source and installation instructions will be announced before launch.`, `<button class="button button--primary" type="button" data-client-download ${account ? '' : 'disabled'}>Download <span aria-hidden="true">↓</span></button><p class="content-note" data-download-status role="status">Animation preview · Client download is not available yet.</p>`], ['Connect to the realm', 'The realm address and client configuration instructions will appear here when testing opens.', '<div class="connection-value">Realm address <strong>To be announced</strong></div><p>Once the realm opens, launch the game, sign in, and create your first character. We’ll publish the final steps before launch.</p><span class="badge">LAUNCH DATE TO BE ANNOUNCED</span>']];
  return `${pageHeader('THE FIRST STEP IS YOURS', 'Your next adventure starts here.', 'Three simple steps. One world of possibilities.', true)}<section class="container page-section narrow">${notice('The realm is in development. Website test accounts are available; client downloads and game connections are not available yet.')}<div class="steps">${steps.map(([title, text, action], i) => {
    const locked = i > 0 && !completedSteps[i - 1];
    return `<article class="step panel${completedSteps[i] ? ' is-complete' : ''}${i === 2 && completedSteps[1] ? ' is-next' : ''}${locked ? ' is-locked' : ''}" data-play-step="${i + 1}" data-progress-owner="${escapeHtml(account?.id || 'guest')}"><span class="step-number" ${locked ? 'aria-hidden="true"' : ''}><span>0${i + 1}</span><svg class="step-check" width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="m5 12 4 4L19 6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg><span class="sr-only" data-step-complete ${completedSteps[i] ? '' : 'hidden'}>Step completed</span></span><div class="step-content" ${locked ? 'inert aria-hidden="true"' : ''}><h2>${title}</h2><p>${text}</p>${action}</div>${locked ? `<div class="step-lock"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="3" stroke="currentColor" stroke-width="1.5"/><path d="M8 10V7a4 4 0 0 1 8 0v3" stroke="currentColor" stroke-width="1.5"/></svg><strong>${title}</strong><span>Complete step ${i} to unlock</span></div>` : ''}</article>`;
  }).join('')}</div></section>`;
}
export async function rankingsPage(category = 'players', query = '') {
  const rows = await dataService.getRankings(category);
  const filtered = rows.filter(row => row.some(value => String(value).toLowerCase().includes(query.toLowerCase())));
  return `${pageHeader('MAKE YOUR MARK', 'The names behind the legends.', 'A little friendly competition. A lot of stories worth telling.')}<section class="container page-section">${notice('Demonstration rankings with fictional players and guilds. No live game data is connected.')}<div class="ranking-toolbar"><div class="tabs" role="group" aria-label="Ranking category">${[['players', 'Players'], ['guilds', 'Guilds'], ['pvp', 'PvP arena']].map(([id, label]) => `<button class="tab ${category === id ? 'is-active' : ''}" data-ranking="${id}" aria-pressed="${category === id}">${label}</button>`).join('')}</div><label class="search-label"><span class="sr-only">Search rankings</span><input type="search" id="ranking-search" placeholder="Search ${category === 'guilds' ? 'guilds' : 'players'}…" value=""></label></div><div id="ranking-results">${table(category === 'guilds' ? ['Rank', 'Guild', 'Faction', 'Members', 'Score'] : ['Rank', 'Player', 'Class', 'Faction', 'Guild', 'Rating'], filtered)}</div><p class="content-note">Showing ${rows.length} example ${category === 'guilds' ? 'guilds' : 'players'} · Preview season</p></section>`;
}
export function accountPage(mode = 'login') {
  const { account, authentication } = authService.state;
  if (account) return profilePage();
  const content = account ? '<h2>Welcome, ' + escapeHtml(account.username) + '.</h2><p>Role: ' + escapeHtml(account.role) + '</p><button class="button button--outline" data-sign-out>Sign out</button><p id="form-message" role="status"></p>' : `<div class="tabs" role="group" aria-label="Account action">${['login', 'register'].map(m => `<button class="tab ${m === mode ? 'is-active' : ''}" data-account="${m}" aria-pressed="${m === mode}">${m === 'login' ? 'Sign in' : 'Create test account'}</button>`).join('')}</div><form id="account-form" data-mode="${mode}"><label for="username">Username</label><input id="username" name="username" autocomplete="username" minlength="3" maxlength="24" required>${mode === 'register' ? '<label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="email" required>' : ''}<label for="password">Password</label><input id="password" name="password" type="password" autocomplete="${mode === 'register' ? 'new-password' : 'current-password'}" minlength="${mode === 'register' ? 12 : 1}" maxlength="256" required>${mode === 'register' ? '<p class="content-note">Use at least 12 characters.</p>' : ''}<button class="button button--primary" type="submit" ${authentication.available || authentication.retryable ? '' : 'disabled'}>${mode === 'login' ? 'Sign in' : 'Create test account'} →</button><p id="form-message" role="status"></p></form>`;
  return `${pageHeader('YOUR PLACE IN THE WORLD', 'Welcome, adventurer.', 'Your account will be the home for your journey.')}<section class="container page-section account-section"><div class="panel account-panel"><div id="account-status" role="status">${notice(escapeHtml(authentication.message))}</div>${authentication.retryable ? '<button class="button button--outline" type="button" data-auth-retry>Retry connection</button>' : ''}${content}</div><div class="account-copy"><h2>A world worth<br>coming home to.</h2><p>Local website test accounts. Game account integration will be connected separately.</p></div></section>`;
}
export function rulesPage() { return `${pageHeader('A BETTER WORLD, TOGETHER', 'Good adventures start with respect.', 'A shared foundation for a welcoming, fair, and lasting community.')}<section class="container page-section narrow">${notice('Proposed community guidelines. Final rules and enforcement policies will be published before launch.')}<div class="rules-list">${rules.map(([title, text], i) => `<article class="rule"><span class="step-number">0${i + 1}</span><div><h2>${title}</h2><p>${text}</p></div></article>`).join('')}</div></section>`; }
export const notFound = () => `${pageHeader('OFF THE BEATEN PATH', 'This trail ends here.', 'We couldn’t find that page. There’s still a whole world to discover.')}<div class="container page-section">${button('Return home →', '#/')}</div>`;
